import{_ as n,C as o,o as p,c as l,aj as r,G as i,a as e,j as t}from"./chunks/framework.BZR1KcQy.js";const C=JSON.parse('{"title":"yersinia","description":"","frontmatter":{},"headers":[],"relativePath":"docs/wi/cyber/yersinia.md","filePath":"docs/wi/cyber/yersinia.md","lastUpdated":1788528112000}'),d={name:"docs/wi/cyber/yersinia.md"};function b(g,a,h,c,u,f){const s=o("ImageZoom");return p(),l("div",null,[a[0]||(a[0]=r('<h1 id="yersinia" tabindex="-1">yersinia <a class="header-anchor" href="#yersinia" aria-label="Permalink to &quot;yersinia&quot;">​</a></h1><h2 id="назначение" tabindex="-1">Назначение <a class="header-anchor" href="#назначение" aria-label="Permalink to &quot;Назначение&quot;">​</a></h2><p>Пакет &#39;yersinia&#39; действительно не найден в ALT Linux p11 (x86_64/i586/noarch).</p><p>ArchWiki: [страница не найдена] (<a href="https://wiki.archlinux.org/title/Yersinia" target="_blank" rel="noreferrer">https://wiki.archlinux.org/title/Yersinia</a>)</p><h2 id="установка" tabindex="-1">Установка <a class="header-anchor" href="#установка" aria-label="Permalink to &quot;Установка&quot;">​</a></h2><h3 id="alt-linux" tabindex="-1">ALT Linux <a class="header-anchor" href="#alt-linux" aria-label="Permalink to &quot;ALT Linux&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yersinia</span></span></code></pre></div><h3 id="kali-linux" tabindex="-1">Kali Linux <a class="header-anchor" href="#kali-linux" aria-label="Permalink to &quot;Kali Linux&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yersinia</span></span></code></pre></div><h2 id="ссылки" tabindex="-1">Ссылки <a class="header-anchor" href="#ссылки" aria-label="Permalink to &quot;Ссылки&quot;">​</a></h2><ul><li><a href="https://packages.altlinux.org/ru/p11/srpms/yersinia/" target="_blank" rel="noreferrer">ALT Linux (srpms)</a></li><li><a href="https://www.kali.org/tools/yersinia/" target="_blank" rel="noreferrer">Kali Tools</a></li><li><a href="https://wiki.archlinux.org/title/Yersinia" target="_blank" rel="noreferrer">ArchWiki</a></li></ul><hr><p>title: &quot;Атаки на сетевое оборудование с Kali Linux&quot; source: &quot;<a href="https://habr.com/ru/articles/326968/" target="_blank" rel="noreferrer">https://habr.com/ru/articles/326968/</a>&quot; author:</p><ul><li>&quot;[[Лука Сафонов]]&quot; published: 2017-04-20 created: 2025-11-18 description: &quot;В данной статье мы рассмотрим актуальные атаки на сетевое оборудование и инструменты, доступные в популярном дистрибутиве Kali Linux для их проведения. Атакуем CISCO маршрутизатор В состав Kali...&quot; tags:</li><li>&quot;clippings&quot;</li></ul><hr>',15)),i(s,{src:"https://habrastorage.org/r/w1560/getpro/habr/post_images/a30/c2d/676/a30c2d676b07070487c16f388a8cb659.png"}),a[1]||(a[1]=e()),a[2]||(a[2]=t("p",null,"В данной статье мы рассмотрим актуальные атаки на сетевое оборудование и инструменты, доступные в популярном дистрибутиве Kali Linux для их проведения.",-1)),a[3]||(a[3]=t("h2",{id:"атакуем-cisco-маршрутизатор",tabindex:"-1"},[e("Атакуем CISCO маршрутизатор "),t("a",{class:"header-anchor",href:"#атакуем-cisco-маршрутизатор","aria-label":'Permalink to "Атакуем CISCO маршрутизатор"'},"​")],-1)),a[4]||(a[4]=t("p",null,"В состав Kali Linux входит несколько инструментов, которые можно использовать для аудита оборудования CISCO. Список можно посмотреть в разделе Vulnerability Analysis — Cisco Tools:",-1)),i(s,{src:"https://habrastorage.org/r/w1560/files/8f3/24f/967/8f324f9674ef4ac6a0a560989e679006.png"}),a[5]||(a[5]=r(' <p><strong>Cisco Audit Tool или CAT</strong><br> Используется для брутфорса пароля при выключенном режиме aaa-mode, брутфорса SNMP community-строк и проверки на уязвимость IOS History bug (<a href="https://tools.cisco.com/security/center/content/CiscoSecurityAdvisory/cisco-sa-19981014-ios-hist" target="_blank" rel="noreferrer">https://tools.cisco.com/security/center/content/CiscoSecurityAdvisory/cisco-sa-19981014-ios-hist</a>)</p><p>Пример использования:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CAT -h 192.168.1.209 -w /root/cisco/wordlist/snmpcommunities -a /root/cisco/wordlist/password_list -i</span></span></code></pre></div>',4)),i(s,{src:"https://habrastorage.org/r/w1560/files/174/0b4/d17/1740b4d172bc4edb8f8c8eab783fd596.png"}),a[6]||(a[6]=e()),a[7]||(a[7]=t("p",null,[t("strong",null,"Cisco Global Exploiter или CGE"),t("br"),e(" Используется для экслпутации известных уязвимостей. Нам доступно 14 атак:")],-1)),i(s,{src:"https://habrastorage.org/r/w1560/files/794/a2d/5f1/794a2d5f1c0b4f1e8e7080bbbc464eb7.png"}),a[8]||(a[8]=r(' <p>Пример использования:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cge.pl 192.168.1.201 3</span></span></code></pre></div>',3)),i(s,{src:"https://habrastorage.org/r/w1560/files/429/4ac/074/4294ac0749854e04abb0a677357c11c8.png"}),a[9]||(a[9]=r(' <p><strong>cisco-ocs</strong><br> Инструмент для автоматизации поиска устройств со стандартными значениями пароля для telnet и режима enable, который может искать устройства в диапазоне адресов. Может использоваться при сканировании больших сетей.</p><p>Пример использования:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cisco-ocs 192.168.1.207 192.168.1.209</span></span></code></pre></div>',4)),i(s,{src:"https://habrastorage.org/r/w1560/files/a02/13d/b00/a0213db009b04cf0ae5f8dd54862adca.png"}),a[10]||(a[10]=r(' <p><strong>cisco-torch</strong><br> Многофункциональный сканер уязвимостей для оборудования Cisco. Может сканировать несколько IP адресов за раз, подгружая из текстового файла. Запускать cisco-torch в Kali Linux следует, находясь в рабочей директории /usr/share/cisco-torch.</p><p>Пример использования:</p><p>Поиск доступных интерфейсов и протоколов и определение типа оборудования.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cisco-torch -A 192.168.1.201</span></span></code></pre></div>',5)),i(s,{src:"https://habrastorage.org/r/w1560/files/107/de9/053/107de905343949da846d69666c29a790.png"}),a[11]||(a[11]=r(' <p>Может использоваться для брутфорса паролей и SNMP community-строк.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cisco-torch -s -b 192.168.1.209</span></span></code></pre></div><p>Для использования своего словаря, его нужно поместить в /usr/share/cisco-torch вместо файла password.txt</p>',4)),i(s,{src:"https://habrastorage.org/r/w1560/files/4ff/fab/e5f/4fffabe5fed249ae923db4cfb0e943b1.png"}),a[12]||(a[12]=r(' <p><strong>copy-router-config.pl и merge-copy-config.pl</strong><br> Инструменты для загрузки текущей конфигурации маршрутизатора cisco при известной community-строке на свой tftp-сервер. В дальнейшем можно модифицировать конфигурацию и снова загрузить на сервер.</p><p>Пример использования:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>copy-router-config.pl 192.168.1.201 192.168.1.3 private</span></span></code></pre></div><p>Для автоматизации подобной атаки, где нас интересует только загрузка конфигурации на свой TFTP-сервер лучше воспользоваться модулем Metasploit auxiliary/scanner/snmp/cisco_config_tftp<br> Или NSE скриптом <a href="https://nmap.org/nsedoc/scripts/snmp-ios-config.html" target="_blank" rel="noreferrer">nmap snmp-ios-config</a>.</p><h2 id="атакуем-l2-протоколы" tabindex="-1">Атакуем L2 протоколы <a class="header-anchor" href="#атакуем-l2-протоколы" aria-label="Permalink to &quot;Атакуем L2 протоколы&quot;">​</a></h2>',6)),i(s,{src:"https://habrastorage.org/r/w1560/files/090/bef/b73/090befb733234bdd86c13ed93af1e00f.png"}),a[13]||(a[13]=r(` <p>Yersinia — многофункциональный инструмент для атак на протоколы L2 (Data Link) уровня OSI.<br> Умеет проводить атаки на DHCP, STP, CDP, DTP, HSRP и другие.</p><p>Работать с Yersinia можно в нескольких режимах:</p><p>Запуск в режиме сервера и управление при помощи команд, похожих на cisco cli.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yersinia -D</span></span>
<span class="line"><span>telnet 127.0.0.1 12000</span></span></code></pre></div><p>Логин и пароль root/root<br> Пароль для перехода в режим enable – tomac</p><ol><li>Запуск в интерактивном режиме</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yersinia -I</span></span></code></pre></div>`,8)),i(s,{src:"https://habrastorage.org/r/w1560/files/34e/3a9/d93/34e3a9d93f244850bdec19ea9e7010a5.png"}),a[14]||(a[14]=e()),a[15]||(a[15]=t("p",null,"Опции управления доступны по нажатии на клавишу h:",-1)),i(s,{src:"https://habrastorage.org/r/w1560/files/59c/db8/ab1/59cdb8ab18c24783a39481a5accb380e.png"}),a[16]||(a[16]=e()),a[17]||(a[17]=t("ol",null,[t("li",null,"Графический интерфейс GTK")],-1)),i(s,{src:"https://habrastorage.org/r/w1560/files/88d/404/8d8/88d4048d89624e069d156daaef32512d.png"}),a[18]||(a[18]=r(' <p>Графический интерфейс может работать нестабильно. В режиме сервера не поддерживает некоторые виды атак, вроде DHCP Rogue server. Так что, основным режимом запуска можно считать интерактивный режим.</p><h2 id="атакуем-dhcp-сервер" tabindex="-1">Атакуем DHCP сервер <a class="header-anchor" href="#атакуем-dhcp-сервер" aria-label="Permalink to &quot;Атакуем DHCP сервер&quot;">​</a></h2><p>В качестве примера продемонстрируем атаку на переполнение пула IP-адресов DHCP сервера. Данная атака может быть использована для выведения из строя корпоративного DHCP сервера и последующая его замещение поддельным, конфигудрация которого настроена таким образом, что весь трафик новых клиентов будет проходить через хост атакующего. Таким образом будет проведена одна из атак MitM.</p><p>На стороне атакующего можно выполнить скрипт nmap для обнаружения DHCP сервера в локальной сети.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nmap -n --script=broadcast-dhcp-discover</span></span></code></pre></div>',6)),i(s,{src:"https://habrastorage.org/r/w1560/files/f0a/519/5df/f0a5195dffa34aa6966f13168193ddb6.png"}),a[19]||(a[19]=e()),a[20]||(a[20]=t("p",null,"Теперь запускаем Yersinia в интерактивном режиме и переходим в режим DHCP выбрав его нажатием клавиши g.",-1)),i(s,{src:"https://habrastorage.org/r/w1560/files/429/e2e/430/429e2e4302484cbc97b2b959069f1031.png"}),a[21]||(a[21]=e()),a[22]||(a[22]=t("p",null,[e("Теперь в этом режиме будут видны все DHCP пакеты, полученные Yersinia."),t("br"),e(" Проверим список выданных адресов DHCP сервера до атаки:")],-1)),i(s,{src:"https://habrastorage.org/r/w1560/files/b3b/331/96e/b3b33196e09f4245999aab5a37063226.png"}),a[23]||(a[23]=e()),a[24]||(a[24]=t("p",null,"Yersinia показывает DHCP пакеты, выловленные из сети:",-1)),i(s,{src:"https://habrastorage.org/r/w1560/files/74b/9a0/f54/74b9a0f5468d4ecb9cf70825e29b7a4b.png"}),a[25]||(a[25]=e()),a[26]||(a[26]=t("p",null,"Если выбрать пакет и нажать сочетание клавиш Shift+L то можно затем при помощи атаки RAW пересылать этот пакет в сеть, или модифицировать его при помощи нажатия клавиши e – переход в режим редактирования пакета.",-1)),a[27]||(a[27]=t("p",null,"При нажатии на клавишу x получаем список доступных атак:",-1)),i(s,{src:"https://habrastorage.org/r/w1560/files/21b/02a/372/21b02a3721724d0e8593c536251885ab.png"}),a[28]||(a[28]=e()),a[29]||(a[29]=t("p",null,"Выбираем 1",-1)),a[30]||(a[30]=t("p",null,"Видим, что начинает отправлять огромное количество DHCP Discover запросов:",-1)),i(s,{src:"https://habrastorage.org/r/w1560/files/40e/fc2/809/40efc2809db246828488f3fd9bc2fea5.png"}),a[31]||(a[31]=e()),a[32]||(a[32]=t("p",null,"Через некоторое время можно остановить атаку нажатием на клавиши L и затем Enter:",-1)),i(s,{src:"https://habrastorage.org/r/w1560/files/c2e/9a5/1ab/c2e9a51ab406414289177f461e527f62.png"}),a[33]||(a[33]=e()),a[34]||(a[34]=t("p",null,"Nmap больше не показывает доступных DHCP серверов в сети. Коропоративный DHCP сервер выведен из строя.",-1)),i(s,{src:"https://habrastorage.org/r/w1560/files/976/339/727/97633972754d41c3a12476c29b0c4a51.png"}),a[35]||(a[35]=e()),a[36]||(a[36]=t("p",null,"Проверим таблицу выданных IP-адресов на роутере:",-1)),i(s,{src:"https://habrastorage.org/r/w1560/files/bbe/859/0fd/bbe8590fd73b4a2e8cd43d8dd6d71ad8.png"}),a[37]||(a[37]=e()),a[38]||(a[38]=t("p",null,"Далее вы можете запустить атаку Rogue DHCP в Yersinia, либо при помощи модуля Metasploit или любым другим способом, чтобы провести MitM атаку.",-1)),i(s,{src:"https://habrastorage.org/r/w1560/files/eef/fe1/f84/eeffe1f848ab4beab498c8bd7d421913.png"}),a[39]||(a[39]=r(' <p>Атаку на истощение пула IP адресов DHCP сервера можно так же провести при помощи инструмента <a href="https://github.com/kamorin/DHCPig" target="_blank" rel="noreferrer">DHCPig</a>. При помощи Yersinia можно проводить атаки и на другие популярные протоколы, такие как STP (Spanning Tree Protocol) и HSRP (Hot Standby Router Protocol), которые так же позволят вам прослушивать трафик в сети.</p><h2 id="атака-на-переполнение-cam-таблицы-коммутатора" tabindex="-1">Атака на переполнение CAM таблицы коммутатора. <a class="header-anchor" href="#атака-на-переполнение-cam-таблицы-коммутатора" aria-label="Permalink to &quot;Атака на переполнение CAM таблицы коммутатора.&quot;">​</a></h2><p>Еще одна атака, которая переполняет CAM таблицу коммутатора, хранящую список MAC адресов, работающих на определенном порту. Некоторые коммутаторы при ее переполнении начинают работать как хабы, рассылая пакеты на все порты, тем самым создавая идеальные условия для проведения атак класса MitM.</p><p>В Kali Linux для проведения данной атаки присутствует инструмент macof</p><p>Пример использования:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>macof -i eth0</span></span></code></pre></div><p>Где eth0 – интерфейс, к которому подключен коммутатор для атаки.</p><h2 id="защита" tabindex="-1">Защита <a class="header-anchor" href="#защита" aria-label="Permalink to &quot;Защита&quot;">​</a></h2><p>Для защиты от подобного рода атак производителями используются различные, обычно проприетарные, технологии. На коммутаторах Cisco следует активировать DHCP Snooping и PortSecutiy во избежание атак на протокол DHCP и CAM Overflow. Для защиты от атак на HSRP и прочие протоколы используются другие технологии. Всегда нужно помнить, что дорогостоящее сетевое оборудование после правильной настройки может существенно повысить безопасность сетевой инфраструктуры, в то же время недонастроенное или настроенное неправильно может само стать инструментом в руках злоумышленника и угрозой безопасности. Выявление уязвимостей сетевого оборудования при проведении <a href="https://red-delta.ru/pentest/" target="_blank" rel="noreferrer">тестирования на проникновение</a> и применение рекомендаций по результатам аудита помогает снизить риски взлома информационной системы злоумышленниками.</p>',10))])}const m=n(d,[["render",b]]);export{C as __pageData,m as default};
